import { Buffer } from 'buffer';

/**
 * Zero-Knowledge Proof (zk-SNARK) verification engine for anonymous policy compliance.
 *
 * Supports Groth16 proofs generated by SnarkJS / Circom over the BN254 curve.
 * Allows users to prove they satisfy spending policies (e.g. KYC verified,
 * country not sanctioned) without revealing their personal identity.
 */

/**
 * Groth16 proof structure as produced by SnarkJS.
 */
export interface Groth16Proof {
  pi_a: string[];
  pi_b: string[][];
  pi_c: string[];
  protocol?: string;
  curve?: string;
}

/**
 * Groth16 verification key structure as produced by SnarkJS.
 */
export interface Groth16VerificationKey {
  protocol: string;
  curve: string;
  nPublic: number;
  vk_alpha_1: string[];
  vk_beta_2: string[][];
  vk_gamma_2: string[][];
  vk_delta_2: string[][];
  vk_alphabeta_12?: string[][][];
  IC: string[][];
}

/**
 * Soroban invocation argument (mirrors the shape returned by `toScVal`).
 */
export interface ScVal {
  type: string;
  value: unknown;
}

/**
 * Minimal shape of the `snarkjs` module we depend on. Loaded lazily so that
 * consumers who never verify proofs do not pay the import cost.
 */
interface SnarkJsModule {
  groth16: {
    verify: (
      vkey: Groth16VerificationKey,
      publicSignals: string[],
      proof: Groth16Proof
    ) => Promise<boolean>;
  };
}

let snarkjsPromise: Promise<SnarkJsModule> | null = null;

/**
 * Lazily load the vetted `snarkjs` library. The dynamic import keeps the
 * dependency optional at module-evaluation time and allows bundlers to
 * code-split it.
 */
async function loadSnarkJs(): Promise<SnarkJsModule> {
  if (!snarkjsPromise) {
    snarkjsPromise = import('snarkjs').then(
      (mod) => (mod as unknown as { default?: SnarkJsModule }).default ?? (mod as unknown as SnarkJsModule)
    );
  }
  return snarkjsPromise;
}

/**
 * Basic structural validation of a Groth16 proof.
 */
function isValidProofShape(proof: unknown): proof is Groth16Proof {
  if (!proof || typeof proof !== 'object') return false;
  const p = proof as Groth16Proof;
  return (
    Array.isArray(p.pi_a) &&
    p.pi_a.length >= 3 &&
    Array.isArray(p.pi_b) &&
    p.pi_b.length >= 3 &&
    p.pi_b.every((row) => Array.isArray(row) && row.length >= 2) &&
    Array.isArray(p.pi_c) &&
    p.pi_c.length >= 3
  );
}

/**
 * Basic structural validation of a Groth16 verification key.
 */
function isValidVKeyShape(vkey: unknown): vkey is Groth16VerificationKey {
  if (!vkey || typeof vkey !== 'object') return false;
  const v = vkey as Groth16VerificationKey;
  return (
    typeof v.nPublic === 'number' &&
    v.nPublic >= 0 &&
    Array.isArray(v.IC) &&
    v.IC.length === v.nPublic + 1 &&
    Array.isArray(v.vk_alpha_1) &&
    Array.isArray(v.vk_beta_2) &&
    Array.isArray(v.vk_gamma_2) &&
    Array.isArray(v.vk_delta_2)
  );
}

/**
 * Verify a Groth16 proof against a verification key and public signals.
 *
 * @param vkey          The Groth16 verification key.
 * @param publicSignals The public inputs (must contain exactly `vkey.nPublic` entries).
 * @param proof         The Groth16 proof.
 * @returns `true` if the proof is valid, `false` otherwise (including tampered inputs).
 */
export async function verifyProof(
  vkey: Groth16VerificationKey,
  publicSignals: string[],
  proof: Groth16Proof
): Promise<boolean> {
  if (!isValidVKeyShape(vkey)) {
    return false;
  }
  if (!isValidProofShape(proof)) {
    return false;
  }
  if (!Array.isArray(publicSignals)) {
    return false;
  }
  // Reject tampered / mismatched public inputs: the count must match exactly.
  if (publicSignals.length !== vkey.nPublic) {
    return false;
  }
  // Every public signal must be a non-empty string (decimal field element).
  if (!publicSignals.every((s) => typeof s === 'string' && s.length > 0)) {
    return false;
  }

  try {
    const snarkjs = await loadSnarkJs();
    const result = await snarkjs.groth16.verify(vkey, publicSignals, proof);
    return result === true;
  } catch {
    // Any malformed input or verification error is treated as an invalid proof.
    return false;
  }
}

/**
 * Maximum size (in bytes) of a Stellar transaction memo.
 */
export const MEMO_MAX_BYTES = 28;

/**
 * Compact wire representation of a proof + public signals used for memo encoding.
 */
interface EncodedProofPayload {
  p: Groth16Proof;
  s: string[];
}

/**
 * Encode a proof and its public signals into a compact string suitable for
 * embedding in a transaction memo.
 *
 * The encoding is `base64(JSON({ p, s }))`. Throws if the encoded payload
 * exceeds the 28-byte memo limit.
 *
 * @param proof         The Groth16 proof.
 * @param publicSignals The public inputs.
 * @returns A base64 string that fits within the memo size limit.
 */
export function encodeProofForMemo(
  proof: Groth16Proof,
  publicSignals: string[]
): string {
  if (!isValidProofShape(proof)) {
    throw new Error('encodeProofForMemo: invalid proof shape');
  }
  if (!Array.isArray(publicSignals)) {
    throw new Error('encodeProofForMemo: publicSignals must be an array');
  }

  const payload: EncodedProofPayload = { p: proof, s: publicSignals };
  const json = JSON.stringify(payload);
  const encoded = Buffer.from(json, 'utf8').toString('base64');

  const byteLength = Buffer.byteLength(encoded, 'utf8');
  if (byteLength > MEMO_MAX_BYTES) {
    throw new Error(
      `encodeProofForMemo: encoded proof is ${byteLength} bytes, exceeds memo limit of ${MEMO_MAX_BYTES} bytes`
    );
  }

  return encoded;
}

/**
 * Decode a proof and its public signals previously produced by
 * {@link encodeProofForMemo}.
 *
 * @param memo The base64 memo string.
 * @returns The decoded proof and public signals.
 */
export function decodeProofFromMemo(memo: string): {
  proof: Groth16Proof;
  publicSignals: string[];
} {
  if (typeof memo !== 'string' || memo.length === 0) {
    throw new Error('decodeProofFromMemo: memo must be a non-empty string');
  }

  let payload: EncodedProofPayload;
  try {
    const json = Buffer.from(memo, 'base64').toString('utf8');
    payload = JSON.parse(json) as EncodedProofPayload;
  } catch {
    throw new Error('decodeProofFromMemo: failed to decode memo payload');
  }

  if (!payload || typeof payload !== 'object' || !payload.p || !Array.isArray(payload.s)) {
    throw new Error('decodeProofFromMemo: malformed memo payload');
  }
  if (!isValidProofShape(payload.p)) {
    throw new Error('decodeProofFromMemo: invalid proof shape');
  }

  return { proof: payload.p, publicSignals: payload.s };
}

/**
 * Convert a hex or base64 string into a byte array.
 */
function toBytes(value: string): Uint8Array {
  if (typeof value !== 'string') {
    throw new Error('toBytes: value must be a string');
  }
  // SnarkJS field elements are decimal strings; encode them as UTF-8 bytes.
  return new Uint8Array(Buffer.from(value, 'utf8'));
}

/**
 * Flatten a Groth16 proof into its constituent field-element strings.
 */
function flattenProof(proof: Groth16Proof): string[] {
  const flat: string[] = [];
  for (const v of proof.pi_a) flat.push(v);
  for (const row of proof.pi_b) for (const v of row) flat.push(v);
  for (const v of proof.pi_c) flat.push(v);
  return flat;
}

/**
 * Encode a proof and its public signals into Soroban contract invocation
 * arguments.
 *
 * The proof points are serialized as a single `Bytes` value (concatenated
 * field elements) and the public signals are serialized as a `Vec<Bytes>`.
 *
 * @param proof         The Groth16 proof.
 * @param publicSignals The public inputs.
 * @returns An array of Soroban `ScVal` arguments: `[proofBytes, publicSignalsVec]`.
 */
export function encodeProofForContract(
  proof: Groth16Proof,
  publicSignals: string[]
): ScVal[] {
  if (!isValidProofShape(proof)) {
    throw new Error('encodeProofForContract: invalid proof shape');
  }
  if (!Array.isArray(publicSignals)) {
    throw new Error('encodeProofForContract: publicSignals must be an array');
  }

  const proofBytes = toBytes(flattenProof(proof).join(','));

  const publicSignalVals: ScVal[] = publicSignals.map((signal) => ({
    type: 'bytes',
    value: toBytes(signal),
  }));

  const proofVal: ScVal = {
    type: 'bytes',
    value: proofBytes,
  };

  const publicSignalsVal: ScVal = {
    type: 'vec',
    value: publicSignalVals,
  };

  return [proofVal, publicSignalsVal];
}